def minesweeper(board):
    rows = len(board)
    result = []
    for r in range(rows):
        cols = len(board[r])
        line = ""
        for c in range(cols):
            if board[r][c] == "*":
                line += "*"
                continue
            count = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < len(board[nr]) and board[nr][nc] == "*":
                        count += 1
            line += str(count)
        result.append(line)
    return result

